// E-V2-02 · Structurer Erreur V2
// Source : 05.V2_Implementation_Technique.md — section 9

const exec  = $json.execution || {};
const error = exec.error || {};

return [{
  json: {
    execution_id : exec.id || null,
    niveau       : 'ERREUR',
    etape        : error.node?.name
                   || exec.lastNodeExecuted
                   || 'INCONNU',
    message      : error.description
                   || error.message
                   || (error.messages
                       ? error.messages.join(' | ')
                       : null)
                   || 'Erreur inconnue'
  }
}];
